import openpyxl, glob, os
files=glob.glob('/tmp/**/*.xlsx', recursive=True)
for p in files:
    try:
        wb=openpyxl.load_workbook(p, data_only=False)
        for ws in wb.worksheets:
            for row in ws.iter_rows(min_row=1, max_row=8, max_col=8):
                vals=[str(c.value) for c in row if c.value is not None]
                s=' '.join(vals)
                if 'FY20 Lane' in s or 'Sherrie' in s or 'Lauri' in s:
                    print('FOUND', p, ws.title)
                    for r in ws.iter_rows(min_row=1, max_row=8, max_col=8):
                        print([c.value for c in r])
                    raise SystemExit
    except Exception as e:
        pass
print('done')
